"""Build offline presentation; original PDF and brand assets remain unchanged."""
from pathlib import Path
from base64 import b64encode
import mimetypes

ROOT = Path(__file__).resolve().parent
PROJECT = ROOT.parent

def asset(path):
    path = Path(path)
    return f'data:{mimetypes.guess_type(path.name)[0]};base64,{b64encode(path.read_bytes()).decode()}'

images = PROJECT / 'site/public/images'
logos = f'<div class="brands"><img src="{asset(ROOT / "assets/logo-linc.png")}" alt="Linc" class="linc"><span aria-hidden="true">×</span><img src="{asset(images / "logo.webp")}" alt="Mecosin" class="mecosin"></div>'

def photo(name, alt, cls='photo'):
    return f'<img class="{cls}" src="{asset(images / name)}" alt="{alt}">'

def card(n, title, text):
    return f'<article class="step card"><span class="number">{n}</span><h3>{title}</h3><p>{text}</p></article>'

def row(n, title, text):
    return f'<article class="step row"><span class="number">{n}</span><div><h3>{title}</h3><p>{text}</p></div></article>'

slides = []
def slide(label, title, lead, body, *, cls='', note='Usulan pengembangan · Linc × Mecosin'):
    i = len(slides) + 1
    slides.append(f'<section class="slide {cls}" id="slide-{i}" aria-label="Slide {i}: {label}"><header>{logos}<span class="chapter">{label}</span></header><div class="content"><h2>{title}</h2><p class="lead">{lead}</p>{body}</div><footer><span>{note}</span><span>{i:02d}</span></footer></section>')

from content_id import populate
populate(slide, photo, row)

