js = '''
const slides=[...document.querySelectorAll('.slide')], shell=document.querySelector('.shell');
const select=document.querySelector('#jump'), count=document.querySelector('#count'), progress=document.querySelector('.progress');
let index=0, revealed=0;
const steps=()=>[...slides[index].querySelectorAll('.step')];
slides.forEach((slide,i)=>{const o=document.createElement('option');o.value=i;o.textContent=`${String(i+1).padStart(2,'0')} · ${slide.querySelector('.chapter').textContent}`;select.append(o)});
function fit(){document.documentElement.style.setProperty('--scale',Math.min(shell.clientWidth/1600,shell.clientHeight/900))}
function render(scroll=false){slides.forEach((s,i)=>{s.classList.toggle('active',i===index);s.inert=i!==index;s.setAttribute('aria-hidden',String(i!==index))});steps().forEach((s,i)=>{s.classList.toggle('pending',i>=revealed);s.inert=i>=revealed;s.setAttribute('aria-hidden',String(i>=revealed))});count.textContent=`${index+1} / ${slides.length}`;select.value=index;progress.style.width=`${(index+1)/slides.length*100}%`;document.querySelector('#prev').disabled=index===0&&revealed===0;document.querySelector('#next').disabled=index===slides.length-1&&revealed===steps().length;document.querySelector('#status').textContent=`Slide ${index+1} dari ${slides.length}. ${slides[index].querySelector('h2').textContent}. Poin ${revealed} dari ${steps().length}`;history.replaceState(null,'',`#slide-${index+1}`);if(scroll&&matchMedia('(max-width:900px) and (orientation:portrait),(max-height:500px) and (max-width:1000px)').matches&&revealed){steps()[revealed-1].scrollIntoView({block:'nearest',behavior:'auto'})}}
function go(i){const nextIndex=Math.max(0,Math.min(slides.length-1,i));document.documentElement.style.setProperty('--travel',nextIndex<index?'-48px':'48px');index=nextIndex;revealed=steps().length;shell.scrollTop=0;render()}
function next(){go(index+1)}
function prev(){go(index-1)}
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{document.querySelector('#status').textContent='Fullscreen tidak tersedia. Gunakan mode fullscreen browser.'}}
const glossary=document.querySelector('#glossary');function toggleGlossary(){if(glossary.open)glossary.close();else glossary.showModal()}
document.querySelector('#next').onclick=next;document.querySelector('#prev').onclick=prev;select.onchange=()=>go(Number(select.value));document.querySelector('#full').onclick=fullscreen;document.querySelector('#terms').onclick=toggleGlossary;document.querySelector('#close').onclick=()=>glossary.close();document.querySelector('#print').onclick=()=>window.print();
document.addEventListener('keydown',e=>{if(glossary.open)return;if(e.target.closest('select,input,textarea,button,a'))return;const k=e.key.toLowerCase();if(['arrowright','arrowleft',' ','pagedown','pageup','backspace','home','end','f','g'].includes(k))e.preventDefault();if(k==='arrowright')e.shiftKey?go(index+1):next();if(k==='arrowleft')e.shiftKey?go(index-1):prev();if([' ','pagedown'].includes(k))next();if(['pageup','backspace'].includes(k))prev();if(k==='home')go(0);if(k==='end')go(slides.length-1,true);if(k==='f')fullscreen();if(k==='g')toggleGlossary()});
let start=null;shell.addEventListener('touchstart',e=>{if(e.touches.length===1&&!e.target.closest('a,button,select'))start=[e.touches[0].clientX,e.touches[0].clientY];else start=null},{passive:true});shell.addEventListener('touchend',e=>{if(!start)return;const dx=e.changedTouches[0].clientX-start[0],dy=e.changedTouches[0].clientY-start[1];if(Math.abs(dx)>70&&Math.abs(dx)>Math.abs(dy)*1.5)dx<0?next():prev();start=null},{passive:true});
addEventListener('resize',fit);addEventListener('hashchange',()=>{const n=Number(location.hash.replace('#slide-',''));if(Number.isInteger(n)&&n>=1&&n<=slides.length)go(n-1)});fit();const initial=Number(location.hash.replace('#slide-',''));go(Number.isInteger(initial)&&initial>=1&&initial<=slides.length?initial-1:0);
'''
